proc eastAsianWidthBits1(a: openArray[uint8]; i: int): uint8 =

  return (a[i shr 3] shr ((i and 7) shl 0)) and 0b1

proc eastAsianWidthLookup(u: int32): uint8 =

  if 0 <= u and u < 262142:

    return eastAsianWidthBits1(eastAsianWidthUint8.toOpenArray(1024, eastAsianWidthUint8.high), int((int(eastAsianWidthUint8[int(u shr 8)])) shl 8)+int(u and 255))

  else:

    return 0

## Public lookups (unicode.go).

proc lookupGeneralCategory*(r: int32): GeneralCategory =
  ## The unicode general category of the rune, or Unassigned if not
  ## found.
  GeneralCategory(gcLookup(r))

proc isMark*(gc: GeneralCategory): bool =
  gc == Mc or gc == Me or gc == Mn

proc isLetter*(gc: GeneralCategory): bool =
  gc == Ll or gc == Lm or gc == Lo or gc == Lt or gc == Lu

proc lookupLineBreak*(ch: int32): LineBreak =
  ## The line break class for the rune, or 0 (XX, Unknown).
  let i = lbLookup(ch)
  if i == 0: return 0
  1'u64 shl (i - 1)

proc lookupGraphemeBreak*(ch: int32): GraphemeBreak =
  ## The grapheme break property for the rune, or 0.
  let i = gbLookup(ch)
  if i == 0: return 0
  1'u16 shl (i - 1)

proc lookupWordBreak*(ch: int32): WordBreak =
  ## The word break property for the rune, or 0.
  let i = wbLookup(ch)
  if i == 0: return 0
  1'u16 shl (i - 1)

proc isWord*(ch: int32): bool =
  ## True for all the runes we may find in a word: either a Number
  ## (Nd, Nl, No) or a rune with the Alphabetic property.
  wordLookup(ch) == 1

proc lookupIndicConjunctBreak*(r: int32): IndicConjunctBreak =
  ## The Indic_Conjunct_Break of the rune, or zero.
  let i = indicCBLookup(r)
  if i == 0: return 0
  1'u8 shl (i - 1)

proc isExtendedPictographic*(ch: int32): bool =
  emojiLookup(ch) == 1

proc isLargeEastAsian*(ch: int32): bool =
  ## Runes with East_Asian_Width of Fullwidth or Wide.
  eastAsianWidthLookup(ch) == 1
